struct timeval new_tv;
new_tv.tv_sec = 1704067200;  // Jan 1, 2024
new_tv.tv_usec = 0;

// Struct timezone is largely obsolete/ignored on modern systems
struct timezone tz_null = { 0 };

// 1. Set time only (tz is NULL)
int res1 = settimeofday(&new_tv, NULL);

// 2. Set time and (optional) timezone
// Requires superuser privileges (CAP_SYS_TIME)
int res2 = settimeofday(&new_tv, &tz_null);

if (res1 == -1) {
    // EPERM if not root
}
